import java.util.concurrent.atomic.AtomicLong;

// JDK options, in order of effort:
// 1. ArrayDeque: a growable circular array, single-threaded.
Deque<Long> dq = new ArrayDeque<>(capacity);
// 2. ArrayBlockingQueue: bounded, FIFO, blocking, multi-producer/consumer.
BlockingQueue<Long> bq = new ArrayBlockingQueue<>(256);

// 3. hand-written SPSC ring for a measured hot path (indices padded apart):
class SpscRing {
    private final long[] buf; private final long mask;
    private final AtomicLong head = new AtomicLong();   // producer-owned
    private final AtomicLong tail = new AtomicLong();   // consumer-owned
    boolean push(long v) {
        long h = head.get();
        if (h - tail.get() == buf.length) return false;   // full
        buf[(int) (h & mask)] = v;
        head.lazySet(h + 1);                                // release
        return true;
    }
    boolean pop() {
        long t = tail.get();
        if (head.get() == t) return false;                 // acquire
        // ... read buf[(int)(t & mask)] ...
        tail.lazySet(t + 1);
        return true;
    }
}
